// Mandi Price Comparator Node (Deterministic Price Rules & Robust Envelope Unwrapping)
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Robust multi-format envelope unwrapping:
  // 1. Webhook body envelope: data.body?.payload || data.body
  // 2. Direct envelope: data.payload
  // 3. Flat payload: data
  const rawBody = (data.body && typeof data.body === 'object') ? data.body : null;
  const payload = (rawBody && rawBody.payload && typeof rawBody.payload === 'object')
    ? rawBody.payload
    : (data.payload && typeof data.payload === 'object' && !data.headers)
      ? data.payload
      : (rawBody || data);

  const eventId = rawBody?.eventId || data.eventId || ('evt_mkt_' + Date.now());
  const eventType = rawBody?.eventType || data.eventType || 'market.price.check_requested';
  const farmId = rawBody?.farmId || data.farmId || 'demo-farm-01';
  const farmerId = rawBody?.farmerId || data.farmerId || 'demo-farmer-01';

  // Extract prices supporting canonical and legacy field names
  const rawCurrent = payload.currentMandiPriceInrPerQtl ?? payload.currentPriceModal ?? payload.modalPriceInrPerQtl ?? payload.currentPrice;
  const rawTarget = payload.farmerTargetPriceInrPerQtl ?? payload.farmerTargetPrice ?? payload.targetPrice;
  const rawMsp = payload.minSupportPriceInrPerQtl ?? payload.mspPrice ?? payload.minSupportPrice;
  const rawMin = payload.minPriceInrPerQtl ?? payload.minPrice;
  const rawMax = payload.maxPriceInrPerQtl ?? payload.maxPrice;

  const commodity = payload.commodityName || payload.commodity || 'Produce';
  const mandi = payload.targetMandi || payload.mandiName || payload.mandi || 'Local Mandi';
  const state = payload.state || 'All-India';
  const priceSource = payload.priceDataSource || payload.dataSource || 'Agmarknet (Govt of India)';
  const observationDate = payload.priceObservationDate || new Date().toISOString();
  const trend7Days = payload.trend7DaysPct !== undefined && !isNaN(Number(payload.trend7DaysPct)) ? Number(payload.trend7DaysPct) : 0;

  // Validate price availability: Do not silently replace missing/invalid price with ₹0!
  const hasValidCurrentPrice = rawCurrent !== undefined && rawCurrent !== null && !isNaN(Number(rawCurrent)) && Number(rawCurrent) > 0;
  const currentPrice = hasValidCurrentPrice ? Number(rawCurrent) : null;
  const targetPrice = (rawTarget !== undefined && rawTarget !== null && !isNaN(Number(rawTarget)) && Number(rawTarget) > 0) ? Number(rawTarget) : null;
  const mspPrice = (rawMsp !== undefined && rawMsp !== null && !isNaN(Number(rawMsp)) && Number(rawMsp) > 0) ? Number(rawMsp) : null;
  const minPrice = (rawMin !== undefined && rawMin !== null && !isNaN(Number(rawMin))) ? Number(rawMin) : null;
  const maxPrice = (rawMax !== undefined && rawMax !== null && !isNaN(Number(rawMax))) ? Number(rawMax) : null;

  let recommendation = '';
  let rationale = '';
  let actionType = '';
  let status = 'success';

  if (!hasValidCurrentPrice) {
    actionType = 'DATA UNAVAILABLE';
    status = 'failed';
    recommendation = `Current market price data for ${commodity} at ${mandi} is currently unavailable from ${priceSource}.`;
    rationale = 'Cannot generate deterministic sell/hold advisory without authenticated current mandi price. Please verify Agmarknet/e-NAM price observation feed.';
  } else if (mspPrice && currentPrice < mspPrice) {
    actionType = 'MSP ALERT / HOLD';
    recommendation = `Current market price (₹${currentPrice}/qtl) is below Government Minimum Support Price (MSP: ₹${mspPrice}/qtl). Do not distress-sell in open mandi.`;
    rationale = `Register at nearest designated official MSP procurement center / NAFED / FCI center to realize guaranteed MSP of ₹${mspPrice}/qtl.`;
  } else if (targetPrice && currentPrice >= targetPrice * 1.05) {
    actionType = 'SELL RECOMMENDED';
    const gainPct = (((currentPrice - targetPrice) / targetPrice) * 100).toFixed(1);
    recommendation = `Current price of ₹${currentPrice}/qtl exceeds your target price (₹${targetPrice}/qtl) by ${gainPct}%. Peak price window active.`;
    rationale = `Favorable selling window at ${mandi}. Recommend executing sale of available inventory.`;
  } else if (targetPrice && currentPrice >= targetPrice) {
    actionType = 'PARTIAL SELL (50%)';
    recommendation = `Current price of ₹${currentPrice}/qtl has reached your target price (₹${targetPrice}/qtl).`;
    rationale = `Recommend liquidating 50% of stock to lock in target profit, while holding remaining 50% if prices rally further.`;
  } else if (trend7Days > 0) {
    actionType = 'HOLD (Price trending upward)';
    recommendation = `Current price (₹${currentPrice}/qtl) is below target (₹${targetPrice || 'N/A'}/qtl), but 7-day trend is upward (+${trend7Days}%).`;
    rationale = `Hold stored stock as price momentum indicates upward recovery across regional mandis.`;
  } else {
    actionType = 'HOLD (Market below target price)';
    recommendation = `Current price (₹${currentPrice}/qtl) is below target (₹${targetPrice || 'N/A'}/qtl) with ${trend7Days <= 0 ? `${trend7Days}%` : 'flat'} trend.`;
    rationale = `Hold stock in safe storage / warehouse receipt financing until demand improves.`;
  }

  const safetyDisclaimer = 'AgriDOST market recommendations are strictly advisory based on published APMC/Agmarknet data. AgriDOST never executes autonomous financial trades or commodity sales. Farmer retains exclusive selling authority.';

  results.push({
    json: {
      eventId,
      eventType,
      farmId,
      farmerId,
      status,
      evaluation: {
        commodity,
        targetMandi: mandi,
        state,
        currentPrice,
        minPrice,
        maxPrice,
        targetPrice,
        mspPrice,
        trend7DaysPct: trend7Days,
        actionType,
        recommendation,
        rationale,
        attribution: {
          source: priceSource,
          timestamp: observationDate
        },
        safetyDisclaimer,
        evaluatedAt: new Date().toISOString()
      }
    }
  });
}

return results;

// Notification Builder Node (Creates bilingual farmer advisory card & signs HMAC callback)
const crypto = require('crypto');
const items = $input.all();
const results = [];
const secret = $env.N8N_WEBHOOK_SECRET || 'agridost_hmac_webhook_signing_secret_2026';
const baseAppUrl = ($env.AGRIDOST_APP_URL || $env.NEXT_PUBLIC_APP_URL || 'http://host.docker.internal:3000').replace(/\/$/, '');

for (const item of items) {
  const data = item.json;
  const evalData = data.evaluation || {};

  const commodity = evalData.commodity || 'Produce';
  const action = evalData.actionType || 'HOLD';
  const currentPrice = evalData.currentPrice;
  const targetPrice = evalData.targetPrice;
  const mspPrice = evalData.mspPrice;
  const mandi = evalData.targetMandi || 'APMC';
  const source = evalData.attribution?.source || 'Agmarknet (Govt of India)';

  // Construct Hindi translation
  let actionHi = '';
  let adviceHi = '';
  if (action === 'DATA UNAVAILABLE') {
    actionHi = 'डेटा अनुपलब्ध';
    adviceHi = `${commodity} के लिए ${mandi} में वर्तमान मूल्य डेटा उपलब्ध नहीं है।`;
  } else if (action === 'SELL RECOMMENDED') {
    actionHi = 'बिक्री की सिफारिश (मजबूत मूल्य)';
    adviceHi = `${commodity} का वर्तमान मंडी भाव (₹${currentPrice}/क्विंटल) आपके लक्ष्य मूल्य (₹${targetPrice}) से अधिक है। ${mandi} में फसल बेचने का उत्तम अवसर है।`;
  } else if (action === 'PARTIAL SELL (50%)') {
    actionHi = 'आंशिक बिक्री (50% बेचें)';
    adviceHi = `${commodity} का भाव आपके लक्ष्य मूल्य ₹${targetPrice}/क्विंटल पर पहुंच गया है। 50% उपज बेचकर लाभ सुरक्षित करें और शेष 50% को रोके रखें।`;
  } else if (action === 'HOLD (Price trending upward)') {
    actionHi = 'रोक कर रखें (मूल्य में बढ़ोतरी का रुझान)';
    adviceHi = `${commodity} का भाव अभी लक्ष्य से कम है परंतु पिछले 7 दिनों में भाव बढ़ रहा है (+${evalData.trend7DaysPct}%)। बेहतर भाव के लिए प्रतीक्षा करें।`;
  } else if (action === 'MSP ALERT / HOLD') {
    actionHi = 'एमएसपी चेतावनी (खुली मंडी में न बेचें)';
    adviceHi = `${commodity} का मंडी भाव (₹${currentPrice}) सरकारी न्यूनतम समर्थन मूल्य (₹${mspPrice}) से कम है। कृपया निकटतम सरकारी खरीद केंद्र पर पंजीकरण कराएं।`;
  } else {
    actionHi = 'रोक कर रखें (बाजार भाव कम)';
    adviceHi = `${commodity} का भाव आपके लक्ष्य मूल्य से नीचे है। अभी उपज सुरक्षित भंडारण में रखें।`;
  }

  const notificationCard = {
    title: {
      en: `Market Alert: ${commodity} - ${action}`,
      hi: `मंडी सूचना: ${commodity} - ${actionHi}`
    },
    message: {
      en: evalData.recommendation,
      hi: adviceHi
    },
    actionRequired: action,
    priceSummary: {
      currentPriceInrPerQtl: currentPrice,
      farmerTargetPriceInrPerQtl: targetPrice,
      mspInrPerQtl: mspPrice,
      mandiName: mandi,
      dataSource: source,
      observationDate: evalData.attribution?.timestamp
    },
    safetyNotice: evalData.safetyDisclaimer
  };

  const timestamp = new Date().toISOString();
  const isFailed = action === 'DATA UNAVAILABLE';
  const callbackPayload = {
    eventId: data.eventId,
    workflowId: 'market-intelligence',
    status: isFailed ? 'failed' : 'success',
    outputSummary: `${action}: ${commodity} @ ${currentPrice !== null ? `₹${currentPrice}/qtl` : 'Unavailable'} (${mandi}) [Source: ${source}]`,
    outputData: {
      evaluation: evalData,
      notification: notificationCard,
      priceSummary: notificationCard.priceSummary
    },
    completedAt: timestamp
  };

  const rawBody = JSON.stringify(callbackPayload);
  const signature = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${rawBody}`)
    .digest('hex');

  const signatureHeader = `t=${timestamp},v1=${signature}`;
  const callbackUrl = `${baseAppUrl}/api/n8n/callback`;

  results.push({
    json: {
      ...data,
      notification: notificationCard,
      callbackPayload,
      callbackUrl,
      rawBody,
      signatureHeader,
      sigTimestamp: timestamp,
      outputSummary: callbackPayload.outputSummary
    }
  });
}

return results;
